local _, ns = ...

-- holidays: English -> Danish. Entries already in ns.Exact (hand-made) are kept.
local names = {
    ["A fishing tournament, held along the coasts of Stranglethorn Vale. Catch as many tastyfish as you can! Will you be the master fisherman who catches forty fish first and wins the grand prize?"] = "En fisketurnering, holdt langs kysterne af Kvælerdorn-dalen. Fang så mange smagsfisk, du kan! Bliver du den mesterfisker, der først fanger fyrretyve fisk og vinder hovedpræmien?",
    ["A time of merriment and celebration, dedicated to the hottest season of the year."] = "En tid for lystighed og fest, viet årets varmeste sæson.",
    ["After the sun sets, the end of Midsummer is celebrated, with an hourly firework extravaganza. To watch the show, visit any capital city or Booty Bay."] = "Når solen går ned, fejres Sankthans' afslutning med et fyrværkeri-ekstravaganza hver time. For at se showet, besøg en hovedstad eller Bytteviken.",
    ["Every year the druids of Moonglade hold a celebration of their city's great triumph over an ancient evil. During the Lunar Festival, citizens of Azeroth have the opportunity to honor their elders by celebrating their sage wisdom, sharing in magnificent feasts, and of course... shooting lots of fireworks!"] = "Hvert år holder druiderne i Månelunden en fest til ære for deres bys store sejr over et gammelt ondt. Under Månefestivalen kan Azerots borgere ære deres ældste ved at fejre deres vise visdom, deles om pragtfulde festmåltider og selvfølgelig... affyre masser af fyrværkeri!",
    ["Greatfather Winter is visiting the cities of Ironforge and Orgrimmar, courtesy of Smokywood Pastures. And throughout Azeroth, it is the season to be jolly!"] = "Storfaderen Vinter besøger byerne Jernsmede og Orgrimgrad, takket være Røgskovs Enge. Og over hele Azerot er det sæson for at være jovial!",
    ["Hallow's End celebrates the break of the Forsaken from the Scourge. Fun and mischief reign as the Innkeepers of Azeroth give treats, and tricks, to whomever asks."] = "Helligaftens Ende fejrer De Forladtes frigørelse fra Svøben. Sjov og ballade råder, mens Azerots kroværter uddeler slik og gækkerier til den, der spørger.",
    ["Show an orphan what the hero's life is like! Visit Orphan Matron Nightingale in Stormwind or Orphan Matron Battlewail in Orgrimmar and make a child's dream come true."] = "Vis en forældreløs, hvordan en helts liv er! Besøg Børnehjemsmoderen Nattergal i Stormvind eller Børnehjemsmoderen Krigsklage i Orgrimgrad og gør et barns drøm til virkelighed.",
    ["Something is in the air in the major cities of Azeroth. Many guards and townsfolk spend their days giving and receiving gifts to other amorous citizens."] = "Der er noget i luften i Azerots store byer. Mange vagter og byfolk bruger deres dage på at give og modtage gaver til andre forelskede borgere.",
    ["The Darkmoon Faire is here, this time at the foot of Thunder Bluff. Meet Silas Darkmoon and his troupe, play games that test mind and nerve, and behold exotic sights from the four corners of Azeroth... and beyond!"] = "Mørkemånens Marked er her, denne gang ved foden af Tordenklippe. Mød Silas Mørkemåne og hans trup, leg lege, der prøver sind og nerver, og beskue eksotiske syn fra Azerots fire hjørner... og videre!",
    ["The Darkmoon Faire is here, this time in idyllic Elwynn Forest. Meet Silas Darkmoon and his troupe, play games that test mind and nerve, and behold exotic sights from the four corners of Azeroth... and beyond!"] = "Mørkemånens Marked er her, denne gang i den idylliske Elwynnskoven. Mød Silas Mørkemåne og hans trup, leg lege, der prøver sind og nerver, og beskue eksotiske syn fra Azerots fire hjørner... og videre!",
    ["The Harvest Festival is a time to commemorate those who have sacrificed their lives to help friends and allies. Feasts are held outside Orgrimmar and Ironforge in honor of these fallen heroes."] = "Høstfestivalen er en tid til at mindes dem, der har ofret deres liv for at hjælpe venner og allierede. Der holdes festmåltider uden for Orgrimgrad og Jernsmede til ære for disse faldne helte.",
    ["The battle at Darkspear Islands is heating up. Join up and prove your might!"] = "Slaget ved Mørkspyd-øerne bliver hedere. Tilmeld dig og bevis din styrke!",
    ["The battle for Alterac Valley grows intense. Greater honor is given to those who pledge sword to their liege and battle in Alterac."] = "Slaget om Alterac-dalen bliver intenst. Større ære gives til dem, der sværger deres sværd til deres herre og kæmper i Alterac.",
    ["The battle for Arathi Basin grows intense. Greater honor is given to those who pledge sword to their liege and battle in Arathi."] = "Slaget om Arathi-bækkenet bliver intenst. Større ære gives til dem, der sværger deres sværd til deres herre og kæmper i Arathi.",
    ["The battle for Warsong Gulch grows intense. Greater honor is given to those who pledge sword to their liege and battle in the Gulch."] = "Slaget om Krigssang-Gulch bliver intenst. Større ære gives til dem, der sværger deres sværd til deres herre og kæmper i Kløften.",
    ["The feast of Noblegarden has arrived. The proving grounds of each race, the place where young heroes first test their strength, each holds cleverly hidden treasure eggs. How many can you find?"] = "Adelshavens Festmåltid er ankommet. Hver races prøvepladser, stedet hvor unge helte første gang afprøver deres styrke, gemmer hver især snedigt skjulte skatteæg. Hvor mange kan du finde?",
}
for en, da in pairs(names) do
    if ns.Exact[en] == nil then ns.Exact[en] = da end
end
